revoke all on function public.handle_new_user() from public, anon, authenticated;
create policy "active offer redirect events can be recorded" on public.redirect_events for insert to anon, authenticated with check (exists (select 1 from public.offers where offers.id = redirect_events.offer_id and offers.merchant_id = redirect_events.merchant_id and offers.status = 'active'));
create or replace function public.record_offer_redirect(p_offer_id uuid,p_referrer text default null,p_user_agent text default null) returns void language plpgsql security invoker set search_path = public as $$ declare merchant uuid; begin select merchant_id into merchant from public.offers where id=p_offer_id and status='active'; if merchant is null then return; end if; insert into public.redirect_events(offer_id,merchant_id,visitor_hash,referrer,user_agent) values(p_offer_id,merchant,encode(digest(coalesce(p_user_agent,'') || coalesce(p_referrer,''),'sha256'),'hex'),left(p_referrer,500),left(p_user_agent,500)); end; $$;
revoke all on function public.record_offer_redirect(uuid,text,text) from public;
grant execute on function public.record_offer_redirect(uuid,text,text) to anon, authenticated;
